#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MOD = 998244353;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<ll> a(n+1);
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    // 前缀和 P 和 Q
    vector<ll> P(n+1), Q(n+1);
    for(int i = 1; i <= n; i++){
        P[i] = P[i-1] + a[i];
        Q[i] = Q[i-1] + P[i];
    }
    // g[x]
    vector<ll> g(n+1);
    for(int x = 1; x <= n; x++){
        ll v = Q[n] - Q[x-1] - Q[n-x];
        v %= MOD;
        if (v < 0) v += MOD;
        g[x] = v;
    }
    // 埃氏筛
    vector<bool> isPrime(n+1, true);
    isPrime[0] = isPrime[1] = false;
    for(int i = 2; i * i <= n; i++){
        if(isPrime[i]){
            for(int j = i*i; j <= n; j += i){
                isPrime[j] = false;
            }
        }
    }
    // 构造 h
    vector<ll> h(n+1);
    for(int i = 1; i <= n; i++){
        h[i] = h[i-1] + (isPrime[i] ? g[i] : 0);
        if (h[i] >= MOD) h[i] -= MOD;
    }
    // 回答查询
    while(m--){
        int l, r;
        cin >> l >> r;
        ll ans = (h[r] - h[l-1]) % MOD;
        if(ans < 0) ans += MOD;
        cout << ans << "\n";
    }
    return 0;
}
